import json
from pathlib import Path
from PIL import Image

base=Path(__file__).parent
d=json.loads((base/'evidence/mobbin-searches-details.json').read_text())
flows={}
for q in d['searches']:
 for f in q['results']: flows.setdefault(f['flow_id'],f)
targeted=json.loads((base/'evidence/mobbin-targeted-results.json').read_text())
for q in targeted['searches']:
 for f in q['flows']:
  flows[f['id']]=dict(flow_id=f['id'],app=f['app_name'],title=f['name'],source_url=f['mobbin_url'],screenshots=[dict(screenshot_id=s['screen_id'],image_url=s['image_url']) for s in f['screens']])
if (base/'evidence/mobbin-github-result.json').exists():
 f=json.loads((base/'evidence/mobbin-github-result.json').read_text())
 flows[f['id']]=dict(flow_id=f['id'],app='GitHub',title=f['name'],source_url=f.get('mobbin_url',f"https://mobbin.com/flows/{f['id']}"),screenshots=[dict(screenshot_id=s['screen_id'],image_url=s['image_url']) for s in f['screens']])

specs=[
 dict(key='e304a20c-fb7b-467a-97de-7f725cd317c1',question='Q1',title='Guide IT between the app and identity provider',actor='university IT',take='Number the configuration handoffs, explain which domains SSO affects, and validate certificate files at upload. Keep the setup state visible until the connection has actually succeeded.',observed='Authentication settings opens a SAML explanation and numbered setup guide. IT copies the service-provider URL and audience into its identity provider, supplies company domain and identity-provider URL, and uploads a certificate. The final screenshot reports an unsupported certificate file type and lists accepted formats.',adaptation='Give university IT a checklist for both systems, copy controls for app-provided values and explicit population scope. Explain invalid file formats next to the upload control before activation.',limitation='The captured flow ends with a certificate-file error; no connection test, activation, successful sign-in, provisioning or group selection is shown. A company email domain is an observed SSO scope cue, not proof of university identity matching.',labels=['Authentication settings and Turn on SSO','SSO explanation and numbered setup guide','Domain, provider URL and certificate inputs','Unsupported certificate file type']),
 dict(key='b7696e33-f9a3-406d-ac04-a210bd88cc1c',question='Q1',title='Choose which directory attributes are synchronized',actor='university IT',take='Let IT enable only the directory fields LearningSpace needs. Describe each field and disclose that changes to existing users may take time to appear.',observed='Directory Sync lists optional auto-mapped attributes with descriptions and enabled/disabled states. An edit dialog provides individual toggles and warns that changes to existing directory users may not appear immediately. After selected toggles are saved, the main table reflects the enabled attributes.',adaptation='Preview the shared fields and default to the minimum institutional data needed. Explain optional fields and propagation timing before IT saves a change.',limitation='This developer-admin example controls optional attributes rather than selecting directory groups. No actual user synchronization, failed update, legal permission or course-membership mapping is demonstrated.',labels=['Directory attribute list, all optional fields disabled','Edit dialog with propagation warning','Selected attributes enabled before Save','Saved enabled/disabled states']),
 dict(key='93a5db68-6f50-4b51-90fd-0b5ae39257a5',question='Q2',title='Keep SAML failure and recovery routes visible',actor='faculty / learner',take='Place a clear retry and administrator-support message beside failed institutional sign-in. A later app screen does not explain how the person authenticated or whether accounts were linked.',observed='The login page offers Slack, Microsoft and SAML SSO. After an email is entered, an error says SAML login failed and suggests trying again or contacting the administrator. The sequence later shows the application home.',adaptation='Distinguish institutional sign-in failure from an authenticated person lacking LearningSpace or course access. Keep the support route visible and make a separate guest route understandable.',limitation='The intermediate successful authentication method is not captured between the SAML error and home. Do not interpret this sequence as successful SAML retry, account linking, first-login provisioning or no-application-access handling. Guest routing remains a proposal.',labels=['Login options and SAML email entry','Email entered for SAML','SAML login failed; retry or administrator guidance','Application home; successful authentication method not captured']),
 dict(key='986b4b4a-9fa5-470e-92fb-ecb1ba4d7a1f',question='Q3',title='Show directory status and system-managed groups',actor='university IT / LearningSpace administrator',take='Distinguish pending people from active users and label who manages a group. Keep group source, membership counts and application assignments visible without equating them with course roles.',observed='The directory route opens People with status filtering; later rows show Pending user action alongside Active. Groups has a Group source type filter, people and applications columns, an Everyone description, and an Okta Administrators group explicitly described as managed by Okta.',adaptation='Expose source and lifecycle status for institutional users and groups. Explain system-managed membership and local exceptions, while representing each person’s course roles separately from institution-wide administration.',limitation='This captures directory navigation and list states, not a continuous provisioning run. No externally sourced group is selected, controlled profile edit is attempted or course permission inherited. An Okta-managed administrator group is not evidence of university group synchronization.',labels=['Directory onboarding context','Directory navigation expanded','People list with active status','People list with pending and active users','Groups with source filter and Okta-managed administrator group'])
]

github='ced1a847-5c4e-49bd-92b4-dcec2b5a8916'
if github in flows:
 specs.insert(1,dict(key=github,question='Q1',title='Test SAML before saving an enforced sign-in policy',actor='university IT',take='Require a connection test before saving enforced SAML. Keep failure feedback close to the configuration so IT can repair setup before institutional users depend on it.',observed='Enterprise onboarding links to Authentication security. Enabling Require SAML authentication reveals sign-on URL, issuer and public-certificate fields plus service-provider information. Save is disabled until a SAML test. The supplied certificate produces an inline X509 format error, Failed: invalid settings beside the test control and an invalid-provider-settings banner.',adaptation='Gate institutional SSO rollout on an explicit test result and explain who will be affected. Preserve configuration context when the test fails so IT can correct it.',limitation='The captured connection test fails and no policy is successfully saved. Enforcing SAML, directory provisioning, account linking and course access remain distinct operations; the flow does not demonstrate them succeeding.',labels=['Enterprise onboarding SAML entry','Authentication security settings','Require SAML fields and test-before-save gate','Configuration values entered','Invalid certificate and failed test','Invalid provider settings banner']))

refs=[]
old=json.loads((base.parent/'access-sharing/references.json').read_text())
oldids={r['id'] for r in old['references']}
for spec in specs:
 key=spec.pop('key');labels=spec.pop('labels');f=flows[key];screens=f['screenshots']
 if spec['observed']=='VERIFY_GITHUB': continue
 assert len(labels)==len(screens)
 paths=[f"assets/mobbin/{s['screenshot_id']}.jpg" for s in screens]
 assert all((base/p).is_file() for p in paths)
 ref=dict(id=f'mobbin:{key}',source='mobbin',app=f['app'],kind='flow',url=f['source_url'],images=[s['image_url'] for s in screens],localAssets=paths,sourceIds=[s['screenshot_id'] for s in screens],source_ids=[s['screenshot_id'] for s in screens],accessedAt='2026-09-08',access_date='2026-09-08',evidenceType='analogy',evidence_type='analogy',counter_example=False,selected=False,boardStepIndices=list(range(len(screens))),**spec)
 ref['steps']=[dict(id=s['screenshot_id'],index=i,imageIndex=i,label=labels[i],localAsset=paths[i]) for i,s in enumerate(screens)]
 ref['assetProvenance']='Full uncropped screenshot images supplied by supported Mobbin MCP image_url links, retrieved promptly and converted to JPEG while retaining original proportions and visible Mobbin attribution. Delivered width is 768 pixels; no higher source resolution was exposed.'
 assert ref['id'] not in oldids,f'Needs reuse rationale: {ref["id"]}'
 assert len(ref['take'].split())<=35,(ref['id'],len(ref['take'].split()))
 refs.append(ref)
(base/'mobbin-references.json').write_text(json.dumps({'module':'university-identity','title':'University identity, directory sync & user import','references':refs},indent=2)+'\n')
(base/'mobbin-assets.json').write_text(json.dumps({r['id']:[str(Path(p).relative_to('assets')) for p in r['localAssets']] for r in refs},indent=2)+'\n')
print(f'{len(refs)} references; {sum(len(r["images"]) for r in refs)} images')
